// Construct a backend error with a fuzzed message and an inner exception.
// Requirements: msg can be any string; inner must be a valid std::exception reference.
// We allocate on the heap to hand ownership to the fuzzer runtime as an output.
std::string outerMsg = FUZZ_PARAM_STR();
std::string innerMsg = FUZZ_PARAM_STR();
std::runtime_error inner(innerMsg);
lsfgvk::backend::error *error = new lsfgvk::backend::error(outerMsg, inner);
// Track that this error has an inner exception for downstream validation/use.
FUZZ_SET_ATTR_INT(error, "has_inner", 1);
// Validation: Construction should succeed; pointer must be non-null by definition of new.
// Any allocation failure would throw and be handled by the fuzzing harness; no additional API constraints to enforce.

// Destructor: simply delete the object. No special caller requirements.
delete error;
// Validation: After deletion, the object must not be reused; we do not return it as an output.

// Enable global leaking mode as a no-op style switch. Safe to call without preconditions.
lsfgvk::backend::makeLeaking();
// Validation: This affects global state; there are no inputs/outputs and no error conditions documented.

// Generate valid 8-bit version components and construct a vk::version object
uint8_t major = *FUZZ_PARAM(uint8_t);
uint8_t minor = *FUZZ_PARAM(uint8_t);
uint8_t patch = *FUZZ_PARAM(uint8_t);

// Invoke the target constructor; heap-allocate so the fuzzer runtime can own it
vk::version *version = new vk::version(major, minor, patch);

// Mark as initialized for downstream stubs
FUZZ_SET_ATTR_INT(version, "initialized", 1);

// Validation: construction of a trivial POD-like wrapper cannot fail; object is returned as output.

// Ensure the vk::version object was constructed by our harness
if (FUZZ_GET_ATTR_INT(version, "initialized") != 1) { FUZZ_BAIL(); }

// Call into() to obtain the packed Vulkan version
uint32_t packed = version->into();

// Store the packed value (masked to fit int attribute) for potential downstream checks
FUZZ_SET_ATTR_INT(version, "packed", static_cast<int>(packed & 0x7fffffff));

// Validation: input object preserved and re-emitted; into() is pure and side-effect free.

// Ensure the semaphore was created as a timeline semaphore and used with the same Vulkan context
if (FUZZ_GET_ATTR_INT(timeline, "is_timeline") != 1) { FUZZ_BAIL(); }
void* creator_vk = FUZZ_GET_ATTR_PTR(timeline, "vk_ptr");
if (creator_vk == nullptr || creator_vk != (void*)vk) { FUZZ_BAIL(); }

// Generate a target value that is >= current to satisfy Vulkan timeline rules
int cur = FUZZ_GET_ATTR_INT(timeline, "timeline_value");
uint64_t delta = (uint64_t)(*FUZZ_PARAM(unsigned int) % 1024u); // small step
uint64_t target = (uint64_t)(cur < 0 ? 0 : (uint64_t)cur) + delta; // ensure non-decreasing

try {
    timeline->signal(*vk, target);
} catch (const std::exception&) {
    // Signal may fail due to device/runtime issues
    FUZZ_BAIL();
}

// Update tracked value to the signaled value
if (target > (uint64_t)cur) {
    FUZZ_SET_ATTR_INT(timeline, "timeline_value", (int)std::min<uint64_t>(target, (uint64_t)INT32_MAX));
}

// Validation: No property assertion here beyond context and monotonicity checks enforced above.

// Validate context association and timeline nature
if (FUZZ_GET_ATTR_INT(timeline, "is_timeline") != 1) { FUZZ_BAIL(); }
void* creator_vk = FUZZ_GET_ATTR_PTR(timeline, "vk_ptr");
if (creator_vk == nullptr || creator_vk != (void*)vk) { FUZZ_BAIL(); }

int cur = FUZZ_GET_ATTR_INT(timeline, "timeline_value");
uint64_t cur64 = (uint64_t)(cur < 0 ? 0 : (uint64_t)cur);

// Choose a target sometimes below/equal to current, sometimes above, to cover both paths
int choose_above = (int)(*FUZZ_PARAM(unsigned int) & 1u);
uint64_t delta = (uint64_t)(*FUZZ_PARAM(unsigned int) % 1024u);
uint64_t target = choose_above ? (cur64 + delta) : (cur64 - std::min<uint64_t>(cur64, delta));

// Use a zero timeout to avoid blocking; this should return immediately
uint64_t timeout = 0;

bool reached = false;
try {
    reached = timeline->wait(*vk, target, timeout);
} catch (const std::exception&) {
    FUZZ_BAIL();
}

// Property: if target <= current value, wait should have already been satisfied
if (target <= cur64) {
    FUZZ_ASSERT(reached, "wait should return true when target <= current timeline value");
}

// Note: We do not modify tracked value on wait; only signal moves the timeline forward.
// Validation: Ensures same Vulkan context, non-blocking wait, and asserts immediate success when target already reached.

// Simply access the underlying handle to exercise the accessor
// Lifetime remains owned by the wrapper; we do not store or destroy the handle
const auto& h = timeline->handle();
(void)h; // suppress unused warning

// Validation: Accessor is side-effect free; object remains in the pool for further use.

// Create a timeline semaphore with a valid Vulkan context and an initial value
// - Avoid importFd: we cannot guarantee a valid external semaphore handle in the fuzzer
// - Optionally request an exportFd to exercise that path safely
uint32_t initial = (uint32_t)(*FUZZ_PARAM(unsigned int) % 1000000u); // small to fit INT attrs
int use_export = (int)(*FUZZ_PARAM(unsigned int) & 1u);
int exported_fd_storage = -1; // storage for optional export fd
std::optional<int*> exportFdOpt = use_export ? std::optional<int*>{ &exported_fd_storage } : std::nullopt;

vk::TimelineSemaphore *timeline = nullptr;
try {
    timeline = new vk::TimelineSemaphore(*vk, initial, std::nullopt, exportFdOpt);
} catch (const std::exception&) {
    // Construction failed (e.g., environment/device/feature issues)
    FUZZ_BAIL();
}

// Track association with the Vulkan context and current timeline value for downstream stubs
